const BATCH_250_EVENTS: HistoryEvent[] = [
  { id: 0, year: '1914', title: { vi: 'Kênh đào Panama mở cửa', en: 'Panama Canal opens' }, summary: { vi: 'Tuyến hàng hải nối Đại Tây Dương và Thái Bình Dương hoàn tất, làm thay đổi thương mại và chiến lược toàn cầu.', en: 'The completed waterway linked the Atlantic and Pacific, reshaping global trade and strategy.' }, region: { vi: 'Trung Mỹ', en: 'Central America' }, category: { vi: 'Hạ tầng', en: 'Infrastructure' }, context: { vi: 'Dự án kéo dài nhiều thập niên, gắn với kỹ thuật y tế, lao động di cư và sự can thiệp của Hoa Kỳ tại Panama.', en: 'The decades-long project involved engineering, public health, migrant labor, and U.S. intervention in Panama.' }, impact: { vi: 'Thời gian và chi phí vận tải giữa hai đại dương giảm mạnh, đồng thời đặt ra di sản thuộc địa và bất bình đẳng lao động.', en: 'Transit times and costs fell sharply, while the canal left legacies of empire and labor inequality.' }, keywords: ['Panama Canal', 'trade', 'engineering'], status: 'curated' },
  { id: 0, year: '1917', title: { vi: 'Cách mạng Nga và sự sụp đổ của chế độ Nga hoàng', en: 'Russian Revolution and the fall of the tsar' }, summary: { vi: 'Khủng hoảng chiến tranh, lương thực và chính trị làm sụp đổ chế độ quân chủ Romanov.', en: 'War, food, and political crises brought down the Romanov monarchy.' }, region: { vi: 'Đông Âu', en: 'Eastern Europe' }, category: { vi: 'Cách mạng', en: 'Revolution' }, context: { vi: 'Chiến tranh thế giới thứ nhất phơi bày những giới hạn của nhà nước đế quốc và làm sâu sắc xung đột giai cấp.', en: 'World War I exposed the limits of imperial government and intensified class conflict.' }, impact: { vi: 'Các chính phủ lâm thời và lực lượng Xô viết cạnh tranh quyền lực, mở đường cho biến động tháng Mười.', en: 'A Provisional Government and soviets competed for power, setting the stage for the October upheaval.' }, keywords: ['Russia', 'revolution', 'World War I'], status: 'curated' },
  { id: 0, year: '1918', title: { vi: 'Đại dịch cúm 1918', en: 'The 1918 influenza pandemic' }, summary: { vi: 'Một đại dịch cúm lan rộng trong bối cảnh chiến tranh, gây tử vong trên nhiều châu lục.', en: 'An influenza pandemic spread across continents amid wartime mobilization.' }, region: { vi: 'Toàn cầu', en: 'Global' }, category: { vi: 'Y tế', en: 'Public health' }, context: { vi: 'Quân đội, vận tải đường biển và đô thị hóa làm tăng tốc độ lan truyền, trong khi kiểm duyệt thời chiến hạn chế thông tin.', en: 'Military mobilization, shipping, and urbanization accelerated transmission while wartime censorship limited information.' }, impact: { vi: 'Đại dịch thúc đẩy năng lực y tế công cộng nhưng cũng cho thấy cái giá của bất bình đẳng và thiếu dữ liệu.', en: 'It stimulated public-health capacity while exposing the costs of inequality and poor data.' }, keywords: ['influenza', 'pandemic', 'public health'], status: 'curated' },
  { id: 0, year: '1919', title: { vi: 'Hội nghị Hòa bình Paris', en: 'Paris Peace Conference' }, summary: { vi: 'Các cường quốc thắng trận đàm phán trật tự hậu chiến và những hiệp ước định hình Trung Đông, châu Âu.', en: 'Victorious powers negotiated a postwar order through treaties reshaping Europe and the Middle East.' }, region: { vi: 'Châu Âu và Trung Đông', en: 'Europe and the Middle East' }, category: { vi: 'Ngoại giao', en: 'Diplomacy' }, context: { vi: 'Sự tan rã của các đế quốc Đức, Áo-Hung, Ottoman và Nga tạo ra những câu hỏi về dân tộc, chủ quyền và thuộc địa.', en: 'The collapse of German, Habsburg, Ottoman, and Russian empires raised questions of nationality, sovereignty, and empire.' }, impact: { vi: 'Hội Quốc Liên ra đời nhưng các thỏa thuận lãnh thổ và cơ chế ủy trị tiếp tục gây tranh chấp lâu dài.', en: 'The League of Nations emerged, but territorial settlements and mandates generated lasting disputes.' }, keywords: ['Versailles', 'League of Nations', 'self-determination'], status: 'curated' },
  { id: 0, year: '1921', title: { vi: 'Chính sách Kinh tế Mới tại Nga Xô viết', en: 'The New Economic Policy' }, summary: { vi: 'Chính quyền Bolshevik nới lỏng kiểm soát kinh tế sau nội chiến và khủng hoảng lương thực.', en: 'The Bolshevik government relaxed economic controls after civil war and famine.' }, region: { vi: 'Nga Xô viết', en: 'Soviet Russia' }, category: { vi: 'Kinh tế', en: 'Economy' }, context: { vi: 'Trưng thu thời chiến và sản xuất suy sụp đã làm gia tăng phản kháng nông dân và khủng hoảng chính trị.', en: 'War requisitions and collapsed production intensified peasant resistance and political crisis.' }, impact: { vi: 'Thị trường giới hạn phục hồi sản xuất nhưng tạo tranh luận về hướng đi xã hội chủ nghĩa.', en: 'A limited market revived production while provoking debate over the direction of socialism.' }, keywords: ['NEP', 'Bolsheviks', 'Soviet economy'], status: 'curated' },
  { id: 0, year: '1922', title: { vi: 'Hiệp ước Washington về hải quân', en: 'Washington Naval Treaty' }, summary: { vi: 'Các cường quốc hàng hải thỏa thuận giới hạn tàu chiến và tỷ lệ hải quân sau Thế chiến I.', en: 'Naval powers agreed to limits on warships and fleet ratios after World War I.' }, region: { vi: 'Thái Bình Dương', en: 'Pacific' }, category: { vi: 'Quan hệ quốc tế', en: 'International relations' }, context: { vi: 'Chi phí chạy đua hải quân và lo ngại xung đột Mỹ-Nhật thúc đẩy ngoại giao kiểm soát vũ khí.', en: 'The cost of naval competition and concern over U.S.–Japanese conflict encouraged arms-control diplomacy.' }, impact: { vi: 'Hiệp ước tạm thời hạn chế hải quân nhưng cũng tạo bất mãn chiến lược tại Nhật Bản.', en: 'The treaty temporarily constrained navies but also generated strategic resentment in Japan.' }, keywords: ['arms control', 'navy', 'Washington Conference'], status: 'curated' },
  { id: 0, year: '1923', title: { vi: 'Hiệp ước Lausanne', en: 'Treaty of Lausanne' }, summary: { vi: 'Hiệp ước quốc tế công nhận biên giới mới của Thổ Nhĩ Kỳ sau chiến tranh giành độc lập.', en: 'The treaty recognized the new international boundaries of Turkey after its war of independence.' }, region: { vi: 'Thổ Nhĩ Kỳ', en: 'Turkey' }, category: { vi: 'Ngoại giao', en: 'Diplomacy' }, context: { vi: 'Thắng lợi quân sự của phong trào Ankara buộc Đồng minh đàm phán lại các điều khoản Sèvres.', en: 'Ankara’s military success forced the Allies to renegotiate the terms of Sèvres.' }, impact: { vi: 'Lausanne củng cố chủ quyền Thổ Nhĩ Kỳ nhưng giải quyết dân cư bằng trao đổi cưỡng bức Hy Lạp–Thổ.', en: 'Lausanne consolidated Turkish sovereignty but institutionalized a coercive Greek–Turkish population exchange.' }, keywords: ['Lausanne', 'Turkey', 'population exchange'], status: 'curated' },
  { id: 0, year: '1924', title: { vi: 'Đạo luật Nhập cư Hoa Kỳ', en: 'U.S. Immigration Act of 1924' }, summary: { vi: 'Hoa Kỳ áp dụng hạn ngạch quốc gia nhằm hạn chế nhập cư, đặc biệt từ Nam và Đông Âu.', en: 'The United States imposed national-origins quotas sharply restricting immigration, especially from southern and eastern Europe.' }, region: { vi: 'Bắc Mỹ', en: 'North America' }, category: { vi: 'Xã hội', en: 'Society' }, context: { vi: 'Chủ nghĩa hạn chế nhập cư, thuyết ưu sinh và di sản Thế chiến I định hình chính sách.', en: 'Restrictionism, eugenic theories, and the legacy of World War I shaped the policy.' }, impact: { vi: 'Đạo luật làm thay đổi cấu trúc di cư xuyên Đại Tây Dương và ảnh hưởng đến người tị nạn nhiều thập niên.', en: 'The act transformed transatlantic migration and affected refugees for decades.' }, keywords: ['immigration', 'United States', 'quotas'], status: 'curated' },
  { id: 0, year: '1925', title: { vi: 'Hiệp ước Locarno', en: 'Locarno Treaties' }, summary: { vi: 'Các hiệp ước châu Âu tìm cách bảo đảm biên giới phía tây của Đức và giảm căng thẳng hậu chiến.', en: 'European treaties sought to guarantee Germany’s western borders and ease postwar tensions.' }, region: { vi: 'Châu Âu', en: 'Europe' }, category: { vi: 'Ngoại giao', en: 'Diplomacy' }, context: { vi: 'Pháp, Đức và Anh thử xây dựng hòa giải trong khuôn khổ Hội Quốc Liên.', en: 'France, Germany, and Britain attempted reconciliation within the League of Nations framework.' }, impact: { vi: 'Locarno tạo không khí hòa dịu ngắn hạn nhưng không bảo đảm các biên giới phía đông.', en: 'Locarno produced short-term détente but left eastern borders less secure.' }, keywords: ['Locarno', 'Germany', 'interwar diplomacy'], status: 'curated' },
];

